   "1 tsp ground cumin",
   "½ tsp ground cardamom",
   "¼ tsp ground cloves",
   "½ tsp paprika",
   "1 tsp salt",
   "3 tbsp olive oil",
   "2 tbsp lemon juice",
   "// Coconut Mashed Potato",
   "600g potatoes — boiled",
   "100ml coconut milk",
   "2 tbsp butter",
   "Salt and white pepper",
   "// Tamarind Reduction",
